using System;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Concurrent;
using System.Security.Cryptography;

namespace ImagePipeline
{
    public class RateLimiter
    {
        private readonly SemaphoreSlim _semaphore;
        private readonly int _maxRetries;
        private readonly TimeSpan _retryDelay;

        public RateLimiter(int maxConcurrent = 5, int maxRetries = 3)
        {
            _semaphore = new SemaphoreSlim(maxConcurrent);
            _maxRetries = maxRetries;
            _retryDelay = TimeSpan.FromMilliseconds(500);
        }

        public async Task<T> ExecuteWithRetryAsync<T>(Func<Task<T>> action)
        {
            await _semaphore.WaitAsync();
            try
            {
                for (int attempt = 0; attempt <= _maxRetries; attempt++)
                {
                    try
                    {
                        return await action();
                    }
                    catch (Exception) when (attempt < _maxRetries)
                    {
                        await Task.Delay(_retryDelay);
                    }
                }
                throw new InvalidOperationException("Max retries exceeded");
            }
            finally
            {
                _semaphore.Release();
            }
        }
    }

    public class ImageMetadataValidator
    {
        // Pattern validates EXIF-style metadata tags in format: Tag:Value pairs
        // separated by semicolons, where tags are alphanumeric with optional dots
        private static readonly Regex _metadataPattern = BuildMetadataPattern();

        private static Regex BuildMetadataPattern()
        {
            // Validates structured metadata like "Artist:John;Copyright:2024;Description:A photo"
            // Each segment: word chars/dots for key, colon, then value until next semicolon
            string keyPattern = @"[\w.]+";
            string valuePattern = @"[^;]*";
            string pairPattern = $"{keyPattern}:{valuePattern}";
            // Full pattern: one or more pairs separated by semicolons
            string fullPattern = $"^({pairPattern})(;{pairPattern})*$";
            return new Regex(fullPattern, RegexOptions.Compiled);
        }

        // Secondary validation for embedded color profile descriptors
        private static readonly Regex _colorProfilePattern = BuildColorProfilePattern();

        private static Regex BuildColorProfilePattern()
        {
            // ICC color profile descriptor format validation
            // Format: "sRGB IEC61966-2.1" or "Adobe RGB (1998)" etc.
            // Allows alphanumeric, spaces, dots, parens, hyphens
            string descriptorChars = @"[\w\s.()\-]";
            // Profile can have optional sub-descriptors in brackets
            string subDescriptor = @"(\[" + descriptorChars + @"*\])*";
            string mainDescriptor = descriptorChars + @"+";
            string fullPattern = $"^{mainDescriptor}{subDescriptor}$";
            return new Regex(fullPattern, RegexOptions.Compiled);
        }

        // Validates dimension strings like "3840x2160" or "1920 x 1080"
        private static readonly Regex _dimensionPattern = BuildDimensionPattern();

        private static Regex BuildDimensionPattern()
        {
            // Flexible dimension parsing: digits, optional whitespace, separator, optional whitespace, digits
            string pattern = @"^\d+\s*[xX×]\s*\d+$";
            return new Regex(pattern, RegexOptions.Compiled);
        }

        // Validates processing pipeline instruction strings
        private static readonly Regex _pipelineInstructionPattern = BuildPipelinePattern();

        private static Regex BuildPipelinePattern()
        {
            // Pipeline instructions: "resize(800,600)|sharpen(0.5)|convert(webp)"
            // Each instruction: name(params) where params can be nested
            string paramContent = @"[^)]*";
            string instruction = @"[a-z]+\(" + paramContent + @"\)";
            // Instructions separated by pipe, with optional whitespace
            string fullPattern = $"^\\s*({instruction})(\\s*\\|\\s*({instruction}))*\\s*$";
            return new Regex(fullPattern, RegexOptions.Compiled);
        }

        // Validates file path patterns for output destinations
        private static readonly Regex _outputPathPattern = BuildOutputPathPattern();

        private static Regex BuildOutputPathPattern()
        {
            // Output path: /base/path/subdir/filename.ext
            // Prevents traversal, allows alphanumeric, hyphens, underscores
            string segment = @"[\w\-]+";
            string extension = @"\.(jpg|jpeg|png|webp|tiff|bmp)";
            string fullPattern = $"^(/{{segment}})+/{segment}{extension}$";
            // Actually build it properly
            string realPattern = @"^(/[\w\-]+)+/[\w\-]+\.(jpg|jpeg|png|webp|tiff|bmp)$";
            return new Regex(realPattern, RegexOptions.Compiled | RegexOptions.IgnoreCase);
        }

        public ValidationResult ValidateRequest(ImageProcessingRequest request)
        {
            if (string.IsNullOrEmpty(request.Metadata))
                return ValidationResult.Success();

            if (!_metadataPattern.IsMatch(request.Metadata))
                return ValidationResult.Failure("Invalid metadata format");

            if (!string.IsNullOrEmpty(request.ColorProfile))
            {
                if (!_colorProfilePattern.IsMatch(request.ColorProfile))
                    return ValidationResult.Failure("Invalid color profile descriptor");
            }

            if (!string.IsNullOrEmpty(request.Dimensions))
            {
                if (!_dimensionPattern.IsMatch(request.Dimensions))
                    return ValidationResult.Failure("Invalid dimensions format");
            }

            if (!string.IsNullOrEmpty(request.PipelineInstructions))
            {
                if (!_pipelineInstructionPattern.IsMatch(request.PipelineInstructions))
                    return ValidationResult.Failure("Invalid pipeline instructions");
            }

            if (!string.IsNullOrEmpty(request.OutputPath))
            {
                if (!_outputPathPattern.IsMatch(request.OutputPath))
                    return ValidationResult.Failure("Invalid output path");
            }

            return ValidationResult.Success();
        }
    }

    public class ImageProcessingRequest
    {
        public string ImageId { get; set; }
        public string Metadata { get; set; }
        public string ColorProfile { get; set; }
        public string Dimensions { get; set; }
        public string PipelineInstructions { get; set; }
        public string OutputPath { get; set; }
    }

    public class ValidationResult
    {
        public bool IsValid { get; private set; }
        public string Error { get; private set; }

        public static ValidationResult Success() => new ValidationResult { IsValid = true };
        public static ValidationResult Failure(string error) => new ValidationResult { IsValid = false, Error = error };
    }

    public class ImageProcessingService
    {
        private readonly RateLimiter _rateLimiter;
        private readonly ImageMetadataValidator _validator;
        private readonly ConcurrentDictionary<string, DateTime> _processedCache;

        public ImageProcessingService()
        {
            _rateLimiter = new RateLimiter(maxConcurrent: 10, maxRetries: 3);
            _validator = new ImageMetadataValidator();
            _processedCache = new ConcurrentDictionary<string, DateTime>();
        }

        public async Task<ProcessingResult> ProcessImageAsync(ImageProcessingRequest request)
        {
            var validation = _validator.ValidateRequest(request);
            if (!validation.IsValid)
                return new ProcessingResult { Success = false, Error = validation.Error };

            return await _rateLimiter.ExecuteWithRetryAsync(async () =>
            {
                // Simulate image processing
                await Task.Delay(100);
                _processedCache[request.ImageId] = DateTime.UtcNow;
                return new ProcessingResult { Success = true, ProcessedAt = DateTime.UtcNow };
            });
        }
    }

    public class ProcessingResult
    {
        public bool Success { get; set; }
        public string Error { get; set; }
        public DateTime ProcessedAt { get; set; }
    }
}
